mod solution;

fn main() {
    let cases = [
    (r#"words=[crab,crate,rust] prefix=cr"#, r#"2"#),
    (r#"words=[cat,dog] prefix=ca"#, r#"1"#),
    (r#"
words=[cat,dog] prefix=ca
"#, r#"1"#),
    (r#"  
words=[crab,crate,rust] prefix=cr
  "#, r#"2"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS trie");
}
